// The console talks to one of two backends with the same shape:
//   server  – `npm start`: the authority runs in Node, events stream over SSE
//   local   – no server reachable (e.g. the hosted demo): the same authority code
//             runs in this tab, with real Ed25519 keys generated by WebCrypto

import { DemoWorld } from '../core/demo-world.js';

export async function connect() {
  const forceLocal = new URLSearchParams(location.search).has('local');
  if (!forceLocal && location.protocol.startsWith('http')) {
    try {
      const res = await fetch('api/health', { cache: 'no-store' });
      if (res.ok && res.headers.get('content-type')?.includes('json')) {
        const body = await res.json();
        if (body.mode === 'server') return new RemoteBackend();
      }
    } catch { /* fall back to in-tab authority */ }
  }
  return LocalBackend.create();
}

class LocalBackend {
  mode = 'local';
  static async create() {
    const b = new LocalBackend();
    b.world = await DemoWorld.create();
    b.listeners = new Set();
    b.unhook = b.world.on((ev) => b.listeners.forEach((fn) => fn(ev)));
    return b;
  }
  on(fn) { this.listeners.add(fn); }
  snapshot() { return this.world.snapshot(); }
  tick() { return this.world.tick(); }
  attack(kind) { return this.world.attack(kind); }
  approve(id, decision) { return this.world.approve(id, decision); }
  revoke(target, reason) { return this.world.revoke(target, reason); }
  delegate(spec) { return this.world.delegate(spec); }
  ledger(opts) { return this.world.ledger(opts); }
  verifyLedger() { return this.world.verifyLedger(); }
  async reset() {
    this.unhook?.();
    this.world = await DemoWorld.create();
    this.unhook = this.world.on((ev) => this.listeners.forEach((fn) => fn(ev)));
    this.listeners.forEach((fn) => fn({ type: 'reset', data: {} }));
  }
}

class RemoteBackend {
  mode = 'server';
  constructor() {
    this.listeners = new Set();
    const es = new EventSource('api/events');
    for (const type of ['decision', 'approval', 'revoked', 'registry', 'ledger', 'reset']) {
      es.addEventListener(type, (e) => {
        const data = JSON.parse(e.data || '{}');
        this.listeners.forEach((fn) => fn({ type, data }));
      });
    }
  }
  async #call(method, path, body) {
    const res = await fetch(path, { method, headers: body ? { 'content-type': 'application/json' } : {}, body: body ? JSON.stringify(body) : undefined });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error || 'request failed');
    return data;
  }
  on(fn) { this.listeners.add(fn); }
  snapshot() { return this.#call('GET', 'api/snapshot'); }
  tick() { return this.#call('POST', 'api/demo/tick', {}); }
  attack(kind) { return this.#call('POST', 'api/demo/attack', { kind }); }
  approve(id, decision) { return this.#call('POST', 'api/demo/approve', { id, decision }); }
  revoke(target, reason) { return this.#call('POST', 'api/demo/revoke', { target, reason }); }
  delegate(spec) { return this.#call('POST', 'api/demo/delegate', spec); }
  ledger({ from = 0, limit = 200 } = {}) { return this.#call('GET', `api/ledger?from=${from}&limit=${limit}`); }
  verifyLedger() { return this.#call('GET', 'api/ledger/verify'); }
  reset() { return this.#call('POST', 'api/demo/reset', {}); }
}
